package com.erni.finalanswer.lastcommand;

import com.erni.finalanswer.audio.LastCommandAudio;
import com.google.gson.*;
import java.util.*;
import java.util.function.*;
import static com.erni.finalanswer.audio.LastCommandAudio.Cue.*;

/** Event adapter only. Never evaluates answers, changes tasks or sends network messages. */
public final class LastCommandAudioEvents {
    private final LastCommandAudio audio;private JsonObject previous,round;private String pendingVictory="";private long victoryAt;private int stressStage;private String closeKey="",faceKey="",voiceKey="";private final BiConsumer<String,String> voice;private final Runnable stopVoice;private boolean voiceRequested,screenChanged;
    private static final LastCommandAudio.Cue[] NOTES={MEMORY_NOTE_RED,MEMORY_NOTE_GREEN,MEMORY_NOTE_BLUE,MEMORY_NOTE_YELLOW};
    private final Map<String,ArrayDeque<String>> pending=new HashMap<>();private long serial;private final LinkedHashSet<Long> panelSeen=new LinkedHashSet<>();private long noteStart=-1;private int noteIndex=-1;private String noteTask="";
    public LastCommandAudioEvents(LastCommandAudio audio){this(audio,(id,key)->{},()->{});}
    public LastCommandAudioEvents(LastCommandAudio audio,BiConsumer<String,String> voice,Runnable stopVoice){this.audio=audio;this.voice=voice;this.stopVoice=stopVoice;}
    private void cancelVoice(){if(voiceRequested){stopVoice.run();voiceRequested=false;}}
    private static boolean symbols(JsonObject r){if(Set.of("SYMBOL","ODD_SYMBOL","POSITION","DECIPHER","REVERSE","SYMBOL_MEMORY").contains(text(r,"taskType")))return true;var t=r==null?null:r.getAsJsonObject("touchscreen");return t!=null&&t.has("options")&&t.get("options").toString().matches(".*[☀☾★◆△□⬟⬡◀▶▲▼].*");}
    static String text(JsonObject o,String k){return o!=null&&o.has(k)?o.get(k).getAsString():"";}static long number(JsonObject o,String k){return o!=null&&o.has(k)?o.get(k).getAsLong():0;}static boolean flag(JsonObject o,String k){return o!=null&&o.has(k)&&o.get(k).getAsBoolean();}
    public static boolean permits(JsonObject r,String element,long now){if(r==null||!flag(r,"expanded"))return true;if(!text(r,"status").equals("PLAYING")||flag(r,"paused")||number(r,"nextAt")>0||now<number(r,"readyAt"))return false;JsonArray ids=r.getAsJsonArray("requiredMechanisms");if(ids==null)return element.equals("TOUCH_PANEL");for(JsonElement id:ids)if(id.getAsString().equals(element))return true;return element.equals("TOUCH_PANEL");}
    private void local(LastCommandAudio.Cue cue,String element,String value,long now){audio.play(cue,"local-"+(++serial));var values=pending.computeIfAbsent(element,k->new ArrayDeque<>());values.addLast(value);while(values.size()>32)values.removeFirst();}
    private static String canonical(String id,String value){if(id.equals("ADJUSTER"))return Integer.toString(Math.round(Float.parseFloat(value)));if(id.equals("HIDDEN_HATCH"))return Boolean.toString(value.equals("OPEN"));return value;}
    public void panel(PanelAction action,long now){if(action.cause()!=PanelAction.Cause.PLAYER||!panelSeen.add(action.sequence()))return;while(panelSeen.size()>512)panelSeen.remove(panelSeen.iterator().next());String id=action.element().name();switch(action.kind()){
        case PRESSED->{local(id.equals("BIG_BUTTON")?BUTTON_PRESS:SMALL_BUTTON_CLICK,id,"*",now);if(id.equals("BIG_BUTTON")&&flag(round,"expanded"))audio.play(CONFIRM,"red-confirm-"+serial);}
        case LEVER_CHANGED->local(LEVER_MOVE,id,canonical(id,action.value()),now);case ADJUSTER_CHANGED,CODE_UPDATED->local(ROTARY_STEP,id,canonical(id,action.value()),now);
        case HATCH_CHANGED->{if(action.value().equals("OPEN")){closeKey="";local(HATCH_OPEN,id,"true",now);}else{closeKey="local-close-"+(++serial);pending.computeIfAbsent(id,k->new ArrayDeque<>()).add("false");}}case LIGHT_CHANGED->local(SMALL_BUTTON_CLICK,id,action.value(),now);default->{}
    }}
    public void touch(String action,long now){if(action.equals("CONFIRM"))local(CONFIRM,"TOUCH_PANEL","*",now);else if(Set.of("SELECT","SELECT_PHYSICAL").contains(action)&&symbols(round))local(SYMBOL_CLICK,"TOUCH_PANEL","*",now);else if(action.equals("ROTATE"))local(CIRCUIT_ROTATE,"TOUCH_PANEL","*",now);else if(action.equals("ADJUST"))local(ROTARY_STEP,"TOUCH_PANEL","*",now);else if(!Set.of("CLIENT_READY","CLOCK_SYNC","VISIBILITY").contains(action))local(SMALL_BUTTON_CLICK,"TOUCH_PANEL","*",now);}
    private void remote(LastCommandAudio.Cue cue,String id,String value,String key,long now){var values=pending.get(id);if(values!=null&&!values.isEmpty()&&values.peekFirst().equals("*")){values.removeFirst();return;}if(values!=null&&values.contains(value)){while(!values.isEmpty())if(values.removeFirst().equals(value))break;return;}audio.play(cue,key);}
    public void snapshot(JsonObject panel,long now){
        JsonObject r=panel.has("testRound")?panel.getAsJsonObject("testRound"):null;if(previous!=null){JsonObject oldRound=previous.getAsJsonObject("testRound");if(!text(previous,"sessionId").equals(text(panel,"sessionId"))||!text(oldRound,"attemptId").equals(text(r,"attemptId"))){pendingVictory="";pending.clear();audio.stopAll();}}round=r;audio.protectedTask(r!=null&&(text(r,"category").equals("MEMORY")||Set.of("SILENCE","DELAYED_EXECUTION","FALSE_COMMAND","TIMING").contains(text(r,"taskType"))||text(r,"scenario").equals("memory")));
        if(previous!=null&&text(previous,"sessionId").equals(text(panel,"sessionId"))){JsonObject old=previous.has("testRound")?previous.getAsJsonObject("testRound"):null;if(!text(r,"taskId").equals(text(old,"taskId"))||!text(r,"attemptId").equals(text(old,"attemptId")))pending.clear();if(!text(r,"taskId").equals(text(old,"taskId"))){cancelVoice();voiceKey=faceKey=closeKey="";screenChanged=true;}String key=text(panel,"sessionId")+":"+text(r,"attemptId")+":"+text(r,"taskId")+":"+number(r,"round");
            boolean won=text(r,"status").equals("WON")&&!text(old,"status").equals("WON");
            if(won){audio.stopNotes();if(flag(r,"expanded"))audio.play(MACHINE_SHUTDOWN,key+":shutdown");else if(!flag(r,"campaign"))audio.play(ANSWER_CORRECT,key+":diagnostic-complete");if(flag(r,"campaign")&&number(r,"step")>=20){pendingVictory=key+":victory:"+number(r,"finishedAt");victoryAt=Math.max(now,number(r,"finishedAt")+700);}}
            else if(text(r,"status").equals("LOST")&&!text(old,"status").equals("LOST")){audio.play(ANSWER_WRONG,key+":failure");}
            else if(r!=null){String feedback=text(r,"feedback"),oldFeedback=text(old,"feedback");boolean valid=Set.of("COMMAND ACCEPTED","WRONG COMMAND").contains(feedback)&&(!feedback.equals(oldFeedback)||!text(r,"taskId").equals(text(old,"taskId"))||number(r,"nextAt")!=number(old,"nextAt"));if(valid){boolean correct=feedback.equals("COMMAND ACCEPTED");String event=key+":"+number(r,"nextAt")+":"+feedback;if(text(r,"taskType").equals("CIRCUIT"))audio.play(correct?CIRCUIT_COMPLETE:CIRCUIT_FAILED,event);audio.play(correct?ANSWER_CORRECT:symbols(r)?SYMBOL_WRONG:ANSWER_WRONG,event);}else if(!flag(r,"campaign")&&number(r,"mistakes")>number(old,"mistakes"))audio.play(ANSWER_WRONG,key+":"+number(r,"mistakes"));else if(text(r,"scenario").equals("mechanisms")&&number(r,"step")>number(old,"step"))audio.play(ANSWER_CORRECT,key+":step:"+number(r,"step"));}
            if(text(r,"taskId").equals(text(old,"taskId"))&&text(r,"attemptId").equals(text(old,"attemptId"))&&number(r,"round")==number(old,"round")&&!text(panel.getAsJsonObject("lastAction"),"action").equals("RESET")){String event=key+":"+number(panel,"sequence");if(!text(panel,"lever").equals(text(previous,"lever")))remote(LEVER_MOVE,"LEVER_MODULE",text(panel,"lever"),event+":lever",now);if(!text(panel,"adjuster").equals(text(previous,"adjuster")))remote(ROTARY_STEP,"ADJUSTER",text(panel,"adjuster"),event+":dial",now);if(flag(panel,"hatch")&&!flag(previous,"hatch")){closeKey="";remote(HATCH_OPEN,"HIDDEN_HATCH","true",event+":hatch",now);}if(!flag(panel,"hatch")&&flag(previous,"hatch")){var q=pending.get("HIDDEN_HATCH");if(q!=null&&!q.isEmpty()&&q.peekFirst().equals("false"))q.removeFirst();else closeKey=event+":hatch-close";}if(!text(panel,"code").equals(text(previous,"code")))remote(ROTARY_STEP,"CODE_PANEL",text(panel,"code"),event+":code",now);
                for(String field:List.of("light","animal","symbol"))if(!text(panel,field).equals(text(previous,field)))remote(field.equals("symbol")?SYMBOL_CLICK:SMALL_BUTTON_CLICK,field.equals("light")?"LIGHT_MODULE":field.equals("animal")?"ANIMAL_PANEL":"SYMBOL_PANEL",text(panel,field),event+":"+field,now);
                JsonObject touch=r!=null?r.getAsJsonObject("touchscreen"):null,oldTouch=old!=null?old.getAsJsonObject("touchscreen"):null;
                if(touch!=null&&oldTouch!=null){if(text(touch,"kind").equals("circuit")&&!Objects.equals(touch.get("board"),oldTouch.get("board")))remote(CIRCUIT_ROTATE,"TOUCH_PANEL","*",event+":wire",now);else if(text(touch,"kind").equals("number")&&!text(touch,"input").equals(text(oldTouch,"input")))remote(SMALL_BUTTON_CLICK,"TOUCH_PANEL","*",event+":key",now);}
                JsonObject last=panel.has("lastAction")?panel.getAsJsonObject("lastAction"):null;if(number(panel,"sequence")>number(previous,"sequence")&&text(last,"action").equals("PRESS")){String id=text(last,"element");remote(id.equals("BIG_BUTTON")?BUTTON_PRESS:SMALL_BUTTON_CLICK,id,"*",event+":press",now);}}
        }
        if(r!=null){int stage=(int)number(r,"step")/5;if(previous!=null&&flag(r,"expanded")&&stage>stressStage&&text(r,"status").equals("PLAYING")){if(stage>=1)audio.play(METAL_CREAK,"stress:"+text(r,"attemptId")+":"+stage);if(stage>=2)audio.play(METAL_CRACK,"critical:"+text(r,"attemptId")+":"+stage);}stressStage=stage;}
        previous=panel;
    }
    public void frame(long now){frame(now,false);}
    public void frame(long now,boolean hatchClosed){audio.update();if(!closeKey.isEmpty()&&hatchClosed){audio.play(HATCH_CLOSE,closeKey);closeKey="";}JsonObject r=round;if(r==null)return;if(!pendingVictory.isEmpty()&&now>=victoryAt){audio.play(VICTORY,pendingVictory);pendingVictory="";}if(!flag(r,"expanded")||!text(r,"status").equals("PLAYING")||flag(r,"paused")){audio.stopNotes();cancelVoice();return;}if(number(r,"nextAt")>0){cancelVoice();return;}
        if(screenChanged){screenChanged=false;if(!text(r,"category").equals("MEMORY")&&!text(r,"taskType").equals("FALSE_COMMAND"))audio.play(SCREEN_TRANSITION,"task-screen:"+text(r,"taskId"));}
        JsonObject screen=r.getAsJsonObject("touchscreen");long reveal=number(screen,"revealUntil");String phase=text(r,"taskType").equals("FIND_CHANGE")?(now>=reveal?"after":now>=reveal-500?"black":"before"):(reveal>0&&now>=reveal?"input":"show");String face=text(r,"taskId")+":"+phase;
        if(!face.equals(faceKey)){boolean prior=!faceKey.isEmpty();faceKey=face;if(text(r,"taskType").equals("FIND_CHANGE")&&prior&&phase.equals("after"))audio.play(SCREEN_TRANSITION,"screen:"+text(r,"taskId")+":after");if(!phase.equals("black")&&symbols(r))audio.play(SYMBOL_APPEAR,"appear:"+face);}
        if(text(r,"taskType").equals("FALSE_COMMAND")&&now>=number(r,"readyAt")){String key=text(r,"attemptId")+":"+text(r,"taskId"),color=text(screen,"spokenColor");if(!key.equals(voiceKey)&&Set.of("RED","GREEN","BLUE","YELLOW").contains(color)){voiceKey=key;voiceRequested=true;voice.accept("PRESS_"+color,"voice:"+key);}}
        JsonArray signals=r.has("signals")?r.getAsJsonArray("signals"):null;long start=number(r,"signalStartedAt"),end=number(r,"inputAt");JsonObject t=r.has("touchscreen")?r.getAsJsonObject("touchscreen"):null;
        if(t!=null&&t.has("flashes")){signals=t.getAsJsonArray("flashes");start=number(r,"readyAt");end=number(t,"revealUntil");}
        long elapsed=now-start;int index=(int)(elapsed/850);if(signals!=null&&elapsed>=0&&now<end&&elapsed%850<120&&index<signals.size()){String value=signals.get(index).getAsString();int color=value.startsWith("SMALL_BUTTON_")?Integer.parseInt(value.substring(13))-1:Integer.parseInt(value);if(color>=0&&color<4&&(start!=noteStart||index!=noteIndex||!text(r,"taskId").equals(noteTask))){noteStart=start;noteIndex=index;noteTask=text(r,"taskId");var cue=NOTES[color];audio.play(cue,"signal:"+text(r,"attemptId")+":"+text(r,"taskId")+":"+start+":"+index);}}
    }
    public void pause(){cancelVoice();closeKey="";audio.pause(true);pendingVictory="";}public void close(){cancelVoice();audio.close();}public void resume(){audio.pause(false);}
}
